window.docContents[172].resolve({"/Overview/#Cvc___lean----High-Level-API-for-CVC5--Overview--Quantifier-elimination":{"contents":"#eval Env.runIO do\n  let solver ← Solver.new\n  let y ← Term.mkSymbol \"y\"\n  let f ← smt! ∃ (x : Int), 0 < x ∧ x < 5 ∧ 2 * y = x - 1\n  let elim ← solver.qe f\n  println! \"elim := {elim}\"\n\n\nelim := (and (>= y 0) (not (>= y 2)))\n\n\n","context":"Cvc.lean -- High-Level API for CVC5\u0009Overview","header":"1.5. Quantifier elimination","id":"/Overview/#Cvc___lean----High-Level-API-for-CVC5--Overview--Quantifier-elimination"}});